from __future__ import annotations

from __future__ import annotations

import gradio as gr


EMPTY_RESPONSE = (
    "Paste a short snapshot of your current work context so the MVP 1 skeleton "
    "can acknowledge it."
)


def respond(message: str, history: list[dict[str, str]] | None = None) -> str:
    """Return deterministic MVP 1 placeholder text for the chat interface."""
    del history

    context = message.strip()
    if not context:
        return EMPTY_RESPONSE

    word_count = len(context.split())
    char_count = len(context)
    return (
        "Attention Firewall MVP 1 received your work context.\n\n"
        f"- Snapshot size: {word_count} words, {char_count} characters.\n"
        "- Current behavior: deterministic deployment skeleton response.\n"
        "- Later MVPs will add structured firewall processing after the Space "
        "foundation is verified."
    )


def build_demo() -> gr.ChatInterface:
    return gr.ChatInterface(
        fn=respond,
        title="Attention Firewall",
        description=(
            "Paste chaotic work context and get a deterministic MVP 1 skeleton "
            "acknowledgement."
        ),
        examples=[
            "I have three urgent threads, a half-written spec, and unclear review feedback.",
            "My deployment is blocked, notes are scattered, and I need the next concrete action.",
        ],
        textbox=gr.Textbox(
            placeholder="Paste work context to triage later...",
            autofocus=True,
            container=False,
        ),
    )


demo = build_demo()


if __name__ == "__main__":
    demo.launch()
